ROOT = Path(__file__).resolve().parents[1]
DATA_PATH = ROOT / "data" / "processed" / "Advertising_clean.csv"
MODEL_PATH = ROOT / "models" / "advertising_sales_model.joblib"

ASSET_DIR = ROOT / "app" / "assets"

def asset_uri(name):
    path = ASSET_DIR / name
    if not path.exists():
        return ""
    mime = "image/png" if path.suffix.lower() == ".png" else "image/jpeg"
    return f"data:{mime};base64," + base64.b64encode(path.read_bytes()).decode("ascii")

def asset_img(name, alt="", cls="asset-img"):
    uri = asset_uri(name)
    return f'<img class="{cls}" src="{uri}" alt="{alt}">' if uri else ""


