@st.cache_data
def load_data():
    return pd.read_csv(DATA_PATH)

@st.cache_resource
def load_model():
    return joblib.load(MODEL_PATH)

df = load_data()
model = load_model()
FEATURES = ["TV","Radio","Newspaper"]
PAGES = ["Overview","Advertising Analysis","Channel Insights","Sales Predictor","Model Performance","Data Explorer","Data Quality"]

def theme(fig, height=430):
    fig.update_layout(
        template="plotly_dark", paper_bgcolor="#07163A", plot_bgcolor="#07163A",
        font=dict(color="#F8FAFC"), height=height,
        colorway=["#168BFF","#7C3CFF","#13E6D0","#FF4FCB","#16D9A5"],
        margin=dict(l=24,r=24,t=64,b=34), legend=dict(bgcolor="rgba(0,0,0,0)")
    )
    fig.update_xaxes(gridcolor="rgba(94,139,220,.16)")
    fig.update_yaxes(gridcolor="rgba(94,139,220,.16)")
    return fig

def section(title, sub):
    icon_map = {
        "Overview":"overview_icon.png",
        "Advertising Analysis":"advertising_analysis_icon.png",
        "Channel Insights":"channel_insights_icon.png",
        "Sales Predictor":"sales_predictor_icon.png",
        "Model Performance":"model_performance_icon.png",
        "Data Explorer":"data_explorer_icon.png",
        "Data Quality":"data_quality_icon.png",
    }
    icon = asset_uri(icon_map.get(title,"overview_icon.png"))
    st.markdown(
        f'<div class="section-title"><img src="{icon}" alt="">{title}</div>'
        f'<div class="section-sub">{sub}</div>',
        unsafe_allow_html=True
    )

def kpi(label,value):
    st.markdown(f'<div class="kpi"><div class="kpi-label">{label}</div><div class="kpi-value">{value}</div></div>', unsafe_allow_html=True)

def sidebar():
    logo = asset_uri("advertising_sales_logo.png")
    with st.sidebar:
        st.markdown(
            f'<div class="brand-title">Advertising Sales</div>'
            f'<div class="brand-sub">Analytics Dashboard</div></div>',
            unsafe_allow_html=True
        )
        st.markdown('<div class="nav-title">Workspace</div>', unsafe_allow_html=True)
        st.radio("Navigation",PAGES,key="page",label_visibility="collapsed")
        st.divider()
        st.markdown('<div class="nav-title">Campaign Filters</div>', unsafe_allow_html=True)
        st.slider("TV Spend",float(df.TV.min()),float(df.TV.max()),(float(df.TV.min()),float(df.TV.max())),key="tv")
        st.slider("Radio Spend",float(df.Radio.min()),float(df.Radio.max()),(float(df.Radio.min()),float(df.Radio.max())),key="radio")
        st.slider("Newspaper Spend",float(df.Newspaper.min()),float(df.Newspaper.max()),(float(df.Newspaper.min()),float(df.Newspaper.max())),key="news")
        if st.button("↺  Reset Filters",use_container_width=True):
            st.session_state.tv=(float(df.TV.min()),float(df.TV.max()))
            st.session_state.radio=(float(df.Radio.min()),float(df.Radio.max()))
            st.session_state.news=(float(df.Newspaper.min()),float(df.Newspaper.max()))
            st.rerun()
        st.divider()
        st.markdown(
            f'<div style="padding:.75rem;border:1px solid #18366B;border-radius:13px;background:#07163A">'
            f'<div style="color:#64748B;font-size:.62rem;text-transform:uppercase;font-weight:900">Active Dataset</div>'
            f'<div style="color:#F8FAFC;font-size:1.2rem;font-weight:950;margin-top:.25rem">{len(df):,}</div>'
            f'<div style="color:#94A3B8;font-size:.68rem">campaign records</div></div>',
            unsafe_allow_html=True
        )
        li=asset_uri("linkedin_icon.png"); gh=asset_uri("github_icon.png")
        st.markdown(
            f'<div style="text-align:center;color:#64748B;font-size:10px;margin-top:16px">'
            f'© 2026 Noura Maher<br><br>'
            f'<a href="https://www.linkedin.com/in/nouramaherelamin/" target="_blank"><img class="social-icon" src="{li}"></a>'
            f'<a href="https://github.com/nouramaherelamin" target="_blank"><img class="social-icon" src="{gh}"></a>'
            f'</div>',
            unsafe_allow_html=True
        )

def filtered():
    x=df.copy()
    x=x[x.TV.between(*st.session_state.tv)]
    x=x[x.Radio.between(*st.session_state.radio)]
    x=x[x.Newspaper.between(*st.session_state.news)]
    return x

def hero():
    hero_uri = asset_uri("hero_advertising_illustration.png")
    st.markdown(f"""
    <div class="hero">
      <img class="hero-art" src="{hero_uri}" alt="Advertising analytics illustration">
      <div class="floatbox">
        <small>ML Engine</small><b>Linear Regression</b>
        <small style="display:block;margin-top:12px">Dataset</small><b>{len(df):,} Campaign Records</b>
      </div>
      <div class="hero-content"><div class="hero-copy">
        <div class="accent"></div>
        <h1>Advertising <span>Sales Analytics</span></h1>
        <p>Turn advertising spend into actionable business insights. Explore TV, Radio, and Newspaper performance, understand Sales relationships, and estimate expected results with machine learning.</p>
        <span class="badge">Interactive analytics · {len(df):,} observations · ML-powered</span>
        <div class="chips">
          <span class="chip">Campaign Analysis</span>
          <span class="chip">Sales Prediction</span>
          <span class="chip">Channel Insights</span>
        </div>
      </div></div>
    </div>
    """,unsafe_allow_html=True)

def overview(x):
    section("Overview","A live market summary based on the active advertising filters.")
    st.markdown(
        f'<div class="channel-strip">'
        f'<div class="channel-card"><img src="{asset_uri("tv_icon.png")}"><span>TV · Electric Blue</span></div>'
        f'<div class="channel-card"><img src="{asset_uri("radio_icon.png")}"><span>Radio · Violet</span></div>'
        f'<div class="channel-card"><img src="{asset_uri("newspaper_icon.png")}"><span>Newspaper · Amber</span></div>'
        f'<div class="channel-card"><img src="{asset_uri("sales_icon.png")}"><span>Sales · Emerald</span></div>'
        f'</div>',
        unsafe_allow_html=True
    )
    vals=[("Campaign Records",f"{len(x):,}"),("Average Sales",f"{x.Sales.mean():.2f}"),("Median Sales",f"{x.Sales.median():.2f}"),("Average TV Spend",f"{x.TV.mean():.2f}"),("Average Radio Spend",f"{x.Radio.mean():.2f}"),("Average Newspaper Spend",f"{x.Newspaper.mean():.2f}")]
    for row in (vals[:3],vals[3:]):
        cs=st.columns(3)
        for c,(l,v) in zip(cs,row):
            with c:kpi(l,v)
    corr=x[FEATURES+["Sales"]].corr()["Sales"].drop("Sales").sort_values(ascending=False)
    st.markdown(f'<div class="insight"><strong>Key Insight</strong> {corr.index[0]} has the strongest linear correlation with Sales in the current filtered data.</div>',unsafe_allow_html=True)
    c1,c2=st.columns(2)
    with c1:
        fig=px.scatter(x,x="TV",y="Sales",size="Radio",hover_data=["Newspaper"],title="TV Advertising vs Sales")
        fig.update_traces(marker_color="#3B82F6");st.plotly_chart(theme(fig,420),use_container_width=True)
    with c2:
        avg=pd.DataFrame({"Channel":FEATURES,"Average Spend":[x[c].mean() for c in FEATURES]})
        fig=px.bar(avg,x="Channel",y="Average Spend",title="Average Advertising Spend",color="Channel",color_discrete_map={"TV":"#168BFF","Radio":"#7C3CFF","Newspaper":"#FFB32E"});st.plotly_chart(theme(fig,420),use_container_width=True)

def analysis(x):
    section("Advertising Analysis","Understand distributions, correlations, and relationships between channels and Sales.")
    c1,c2=st.columns(2)
    with c1:
        long=x[FEATURES].melt(var_name="Channel",value_name="Spend")
        st.plotly_chart(theme(px.box(long,x="Channel",y="Spend",color="Channel",title="Advertising Spend Distribution")),use_container_width=True)
    with c2:
        st.plotly_chart(theme(px.scatter_matrix(x,dimensions=FEATURES+["Sales"],title="Advertising & Sales Matrix"),520),use_container_width=True)
    corr=x[FEATURES+["Sales"]].corr()
    st.plotly_chart(theme(px.imshow(corr,text_auto=".2f",color_continuous_scale=["#010A27","#073E9C","#168BFF","#7C3CFF","#13E6D0"],title="Correlation Matrix"),500),use_container_width=True)

def insights(x):
    section("Channel Insights","Compare the three advertising channels and inspect their individual relationships with Sales.")
    summary=pd.DataFrame({"Channel":FEATURES,"Average Spend":[x[c].mean() for c in FEATURES],"Maximum Spend":[x[c].max() for c in FEATURES],"Sales Correlation":[x[c].corr(x.Sales) for c in FEATURES]})
    cs=st.columns(3)
    for c,(_,r) in zip(cs,summary.iterrows()):
        with c:kpi(f"{r.Channel} Correlation",f"{r['Sales Correlation']:.3f}")
    ch=st.selectbox("Choose channel",FEATURES)
    fig=px.scatter(x,x=ch,y="Sales",title=f"{ch} Advertising vs Sales")
    fig.update_traces(marker_color="#3B82F6")
    st.plotly_chart(theme(fig,470),use_container_width=True)
    st.dataframe(summary,use_container_width=True,hide_index=True)

def predictor():
    section("Sales Predictor","Create an advertising budget profile and estimate expected Sales.")
    a,b=st.columns([1.2,.8],gap="large")
    with a:
        st.markdown('<div class="predict"><b style="color:#10B981">CAMPAIGN PROFILE</b>',unsafe_allow_html=True)
        tv=st.number_input("TV Advertising",0.0,float(df.TV.max()*1.5),float(df.TV.median()),.1)
        radio=st.number_input("Radio Advertising",0.0,float(df.Radio.max()*1.5),float(df.Radio.median()),.1)
        news=st.number_input("Newspaper Advertising",0.0,float(df.Newspaper.max()*1.5),float(df.Newspaper.median()),.1)
        go=st.button("✦  Estimate Sales",type="primary",use_container_width=True)
        st.markdown("</div>",unsafe_allow_html=True)
    with b:
        st.markdown('<div class="predict"><b style="color:#10B981">AI ESTIMATE</b><div style="height:14px"></div>',unsafe_allow_html=True)
        if go:
            row=pd.DataFrame([{"TV":tv,"Radio":radio,"Newspaper":news}])
            pred=max(0,float(model.predict(row)[0]))
            st.markdown(f'<div class="result"><div style="color:#94A3B8;font-size:.72rem;text-transform:uppercase">Estimated Sales</div><div class="price">{pred:.2f}</div><div style="color:#94A3B8;font-size:.8rem;margin-top:.4rem">Model estimate</div></div>',unsafe_allow_html=True)
        else:
            st.markdown('<div class="result" style="min-height:205px"><div style="font-size:2rem">◈</div><b style="display:block;margin-top:10px">Ready to predict</b><span style="color:#9AA8A0;font-size:.8rem">Set the advertising budget and run the estimator.</span></div>',unsafe_allow_html=True)
        st.markdown("</div>",unsafe_allow_html=True)
    st.markdown('<div class="insight"><strong>Prediction note</strong> This is a machine-learning estimate based on historical observations, not a guaranteed business result.</div>',unsafe_allow_html=True)

def performance():
    section("Model Performance","Evaluation of the trained Linear Regression model on a held-out test set.")
    X=df[FEATURES];y=df.Sales
    xt,xv,yt,yv=train_test_split(X,y,test_size=.2,random_state=42)
    pred=model.predict(xv)
    mae=mean_absolute_error(yv,pred);rmse=np.sqrt(mean_squared_error(yv,pred));r2=r2_score(yv,pred)
    cs=st.columns(5)
    for c,(l,v) in zip(cs,[("Model","Linear Regression"),("MAE",f"{mae:.3f}"),("RMSE",f"{rmse:.3f}"),("R²",f"{r2:.3f}"),("Test Rows",str(len(yv)))]):
        with c:kpi(l,v)
    p=pd.DataFrame({"Actual":yv.values,"Predicted":pred})
    fig=px.scatter(p,x="Actual",y="Predicted",title="Actual vs Predicted Sales")
    lo=min(p.min());hi=max(p.max())
    fig.add_trace(go.Scatter(x=[lo,hi],y=[lo,hi],mode="lines",name="Perfect prediction",line=dict(color="#10B981",dash="dash")))
    st.plotly_chart(theme(fig,480),use_container_width=True)

def explorer(x):
    section("Data Explorer","Inspect and download the currently filtered advertising records.")
    q=st.text_input("Search dataset",placeholder="Type a value...")
    view=x.copy()
    if q.strip():
        mask=view.astype(str).apply(lambda c:c.str.contains(q,case=False,na=False,regex=False)).any(axis=1)
        view=view[mask]
    st.download_button("↓ Download filtered CSV",view.to_csv(index=False).encode(),file_name="filtered_advertising_data.csv",mime="text/csv")
    st.dataframe(view,use_container_width=True,hide_index=True)

def quality():
    section("Data Quality","Quality checks for the processed Advertising dataset.")
    cards=[("Rows",f"{len(df):,} records"),("Columns",f"{df.shape[1]} variables"),("Missing Values",f"{int(df.isna().sum().sum())}"),("Duplicate Rows",f"{int(df.duplicated().sum())}"),("Target","Sales"),("Predictors","TV · Radio · Newspaper")]
    cs=st.columns(3)
    for i,(a,b) in enumerate(cards):
        with cs[i%3]:st.markdown(f'<div class="quality"><b>{a}</b><span>{b}</span></div>',unsafe_allow_html=True)
    st.dataframe(pd.DataFrame({"Column":df.columns,"Dtype":[str(v) for v in df.dtypes],"Missing":[int(df[c].isna().sum()) for c in df.columns],"Unique":[int(df[c].nunique()) for c in df.columns]}),use_container_width=True,hide_index=True)

